-- Route/review binding at the accepted objects, in their original transaction.
-- Source prepared only; not applied or PG-verified in this slice.


CREATE OR REPLACE FUNCTION c1_api.review_material(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;r c1_private.reviews;BEGIN s=c1_private.auth(n,q,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->>'review_id')::uuid AND subject=s.subject;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;IF r.kind='publish' THEN IF r.payload->>'store' IS DISTINCT FROM q->>'store' OR r.payload->>'meal' IS DISTINCT FROM q->>'meal' THEN PERFORM c1_private.fail('NOT_FOUND');END IF;PERFORM c1_private.owner_auth(n,s,r.payload->>'store','catalog');END IF;RETURN jsonb_build_object('kind',r.kind,'payload',r.payload,'scope',(SELECT manifest->'stores'->(r.payload->>'store') FROM c1_private.deployment WHERE ns=n));END $$;

CREATE OR REPLACE FUNCTION c1_api.intent_retry(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;i c1_private.intents;BEGIN s=c1_private.auth(n,q,true);PERFORM c1_private.guard(n);SELECT * INTO i FROM c1_private.intents WHERE ns=n AND principal=s.subject AND action=q->>'action' AND idem=q->>'key';IF FOUND AND q->>'action' IN('publish','list','pause','close','lock','handover','settle') THEN IF i.payload->>'store' IS DISTINCT FROM q->>'store' OR (i.action='publish' AND i.payload->>'meal' IS DISTINCT FROM q->>'meal') THEN PERFORM c1_private.fail('NOT_FOUND');END IF;END IF;IF q->>'action' IN('publish','list','pause','close') THEN PERFORM c1_private.owner_auth(n,s,q->>'store','catalog');ELSIF q->>'action' IN('lock','handover') THEN PERFORM c1_private.owner_auth(n,s,q->>'store','redeem');ELSIF q->>'action'='settle' THEN PERFORM c1_private.owner_auth(n,s,q->>'store','payout');ELSIF q->>'action' IN('fund','refund') AND NOT EXISTS(SELECT 1 FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject AND enabled) THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;RETURN coalesce(c1_private.idem(n,s,q->>'action',q),'{}');END $$;

CREATE OR REPLACE FUNCTION c1_api.draft_publish(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;r c1_private.reviews;dr c1_private.drafts;st c1_private.stores;h c1_private.catalog_head;p jsonb;old jsonb;gr bigint;original_payload jsonb;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','catalog');SELECT payload INTO original_payload FROM c1_private.intents WHERE ns=n AND principal=s.subject AND action='publish' AND idem=q->>'key';IF FOUND THEN IF original_payload->>'store' IS DISTINCT FROM q->>'store' OR original_payload->>'meal' IS DISTINCT FROM q->>'meal' THEN PERFORM c1_private.fail('NOT_FOUND');END IF;PERFORM c1_private.owner_auth(n,s,original_payload->>'store','catalog');END IF;old=c1_private.idem(n,s,'publish',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND subject=s.subject AND kind='publish';IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;IF r.payload->>'store' IS DISTINCT FROM q->>'store' OR r.payload->>'meal' IS DISTINCT FROM q->>'meal' THEN PERFORM c1_private.fail('NOT_FOUND');END IF;gr=c1_private.owner_auth(n,s,r.payload->>'store','catalog');p=r.payload;SELECT * INTO dr FROM c1_private.drafts WHERE ns=n AND store=p->>'store' AND meal=p->>'meal';SELECT * INTO st FROM c1_private.stores WHERE ns=n AND store=dr.store;SELECT * INTO h FROM c1_private.catalog_head WHERE ns=n AND store=dr.store AND meal=dr.meal;IF dr.revision<>(p->>'draftRevision')::bigint OR coalesce(h.version,0)<>(p->>'currentVersion')::bigint OR st.control_revision<>(p->>'controlRevision')::bigint THEN PERFORM c1_private.fail('CONFLICT');END IF;
 IF EXISTS(SELECT 1 FROM c1_private.terms WHERE ns=n AND store=dr.store AND meal=dr.meal AND version=(p->>'version')::bigint) THEN PERFORM c1_private.fail('CONFLICT');END IF;
 INSERT INTO c1_private.terms VALUES(n,dr.store,dr.meal,(p->>'version')::bigint,decode(q->>'body','base64'),dr.image,c1_private.h(q->>'body_digest'),dr.image_digest,c1_private.h(q->>'terms_hash'),dr.price,dr.windows,dr.name,dr.description,true);
 p=(p-'image')||jsonb_build_object('deadline',d.now+300,'body_digest','0x'||(q->>'body_digest'),'image_digest','0x'||encode(dr.image_digest,'hex'),'terms_hash','0x'||(q->>'terms_hash'),'price',dr.price::text);RETURN c1_private.new_intent(n,s,'publish',q,p,false,gr);END $$;

CREATE OR REPLACE FUNCTION c1_api.settle_confirm(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE d c1_private.deployment;s c1_private.sessions;r c1_private.reviews;u c1_private.units;old jsonb;res jsonb;gr bigint;original_payload jsonb;BEGIN d=c1_private.guard(n);s=c1_private.auth(n,q,true);gr=c1_private.owner_auth(n,s,q->>'store','payout');SELECT payload INTO original_payload FROM c1_private.intents WHERE ns=n AND principal=s.subject AND action='settle' AND idem=q->>'key';IF FOUND THEN IF original_payload->>'store' IS DISTINCT FROM q->>'store' THEN PERFORM c1_private.fail('NOT_FOUND');END IF;PERFORM c1_private.owner_auth(n,s,original_payload->>'store','payout');END IF;old=c1_private.idem(n,s,'settle',q);IF old IS NOT NULL THEN RETURN old;END IF;PERFORM c1_private.guard(n,true);SELECT * INTO r FROM c1_private.reviews WHERE ns=n AND id=(q->'client'->>'reviewId')::uuid AND subject=s.subject AND kind='settle';IF NOT FOUND OR r.expires<=d.now THEN PERFORM c1_private.fail('STALE_REVIEW');END IF;IF r.payload->>'store' IS DISTINCT FROM q->>'store' THEN PERFORM c1_private.fail('NOT_FOUND');END IF;gr=c1_private.owner_auth(n,s,r.payload->>'store','payout');SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=r.payload->>'store' AND seq=(r.payload->>'seq')::int;IF u.bucket<>'H' OR u.active_op IS NOT NULL THEN PERFORM c1_private.fail('CONFLICT');END IF;IF NOT c1_private.content_available(n,u.store,u.meal,u.version) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;res=c1_private.new_intent(n,s,'settle',q,r.payload||jsonb_build_object('deadline',d.now+300),true,gr);UPDATE c1_private.units SET active_op=(res->>'id')::uuid WHERE ns=n AND store=u.store AND seq=u.seq;RETURN res;END $$;

REVOKE ALL ON FUNCTION c1_api.review_material(text,jsonb),c1_api.intent_retry(text,jsonb),c1_api.draft_publish(text,jsonb),c1_api.settle_confirm(text,jsonb) FROM PUBLIC;
